// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AISkill) predicate.AISkill {
	return predicate.AISkill(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AISkill) predicate.AISkill {
	return predicate.AISkill(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AISkill) predicate.AISkill {
	return predicate.AISkill(sql.NotPredicates(p))
}
